import{_ as i,C as d,o as s,c as o,a2 as a,E as n}from"./chunks/framework.wVcpyw2-.js";const y=JSON.parse('{"title":"地图与定位","description":"灵萌地图与定位全量配置：高德 Key、IP 归属地四选一、区域距离限制、ip2region 离线库与 CDN 代理部署说明。","frontmatter":{"title":"地图与定位","description":"灵萌地图与定位全量配置：高德 Key、IP 归属地四选一、区域距离限制、ip2region 离线库与 CDN 代理部署说明。"},"headers":[],"relativePath":"features/map.md","filePath":"features/map.md","lastUpdated":1785577569000}'),r={name:"features/map.md"};function l(p,t,h,c,g,k){const e=d("DocOverview");return s(),o("div",null,[t[0]||(t[0]=a('<h1 id="地图与定位" tabindex="-1">地图与定位 <a class="header-anchor" href="#地图与定位" aria-label="Permalink to &quot;地图与定位&quot;">​</a></h1><p>灵萌的「定位」包含三类能力，配置入口分散在管理后台多个 Tab 与服务端 <code>config.yaml</code>：</p><table tabindex="0"><thead><tr><th>能力</th><th>典型用途</th><th>主要配置</th></tr></thead><tbody><tr><td><strong>前端地图</strong></td><td>H5/小程序选点、地图展示</td><td><code>amap_webkey</code>、<code>amap_security_key</code></td></tr><tr><td><strong>服务端地理服务</strong></td><td>POI 搜索、天气、距离计算</td><td><code>amap_key</code>（Web 服务 Key）</td></tr><tr><td><strong>IP 归属地</strong></td><td>区域门禁、注册属地、内容 IP 快照</td><td><code>ali_ip_location_provider</code> + AppCode / 高德 Key / ip2region xdb</td></tr></tbody></table>',3)),n(e,{page:"map"}),t[1]||(t[1]=a(`<hr><h2 id="配置项速查-数据库-system-config" tabindex="-1">配置项速查（数据库 <code>system_config</code>） <a class="header-anchor" href="#配置项速查-数据库-system-config" aria-label="Permalink to &quot;配置项速查（数据库 \`system_config\`）&quot;">​</a></h2><p>管理后台 <strong>系统设置 → 系统配置</strong> 保存后即时生效（ip2region xdb 路径除外，须改 <code>config.yaml</code> 并重启）。</p><h3 id="tab-amap" tabindex="-1">高德地图 Tab <a class="header-anchor" href="#tab-amap" aria-label="Permalink to &quot;高德地图 Tab {#tab-amap}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>amap_key</code></td><td>Web 服务 Key</td><td>后端 POI、天气、距离；选「高德高级 IP」时也用于 IP 归属地</td></tr><tr><td><code>amap_webkey</code></td><td>JS API Key</td><td>前端地图组件，与 Web 服务 Key <strong>不是同一个</strong></td></tr><tr><td><code>amap_security_key</code></td><td>jscode</td><td>2021 年后前端地图必配的安全密钥</td></tr></tbody></table><p>申请：<a href="https://console.amap.com/dev/key/app" target="_blank" rel="noreferrer">高德控制台</a></p><h3 id="tab-aliyun" tabindex="-1">阿里云 Tab <a class="header-anchor" href="#tab-aliyun" aria-label="Permalink to &quot;阿里云 Tab {#tab-aliyun}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><code>ali_ip_location_provider</code></td><td>IP 归属地提供方，见下表</td></tr><tr><td><code>ali_appcode</code></td><td>阿里云市场 AppCode；lundear/kzipquery 查 IP 必填；快递、地址解析等仍可能需要</td></tr></tbody></table><table tabindex="0"><thead><tr><th>值</th><th>显示名</th><th>IPv6</th><th>凭证</th></tr></thead><tbody><tr><td><code>lundear</code></td><td>IP/IPv6 归属地查询</td><td>支持，优先 IPv6</td><td>AppCode</td></tr><tr><td><code>kzipquery</code></td><td>高精准全球 IP</td><td>不支持（仅 IPv4）</td><td>AppCode</td></tr><tr><td><code>amap</code></td><td>高德高级 IP</td><td>支持，优先 IPv6</td><td><code>amap_key</code>（Web 服务 Key）</td></tr><tr><td><code>ip2region</code></td><td>ip2region 离线库</td><td>v6 xdb 存在时支持</td><td>无（本地 xdb）</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">CDN / IPv6</p><p>站点已接入 CDN（如 EdgeOne）且用户可能走 IPv6 时，<strong>不要</strong>选 <code>kzipquery</code>。应选 <code>lundear</code>、<code>amap</code>，或部署 ip2region 的 v4 + v6 xdb。</p></div><h3 id="tab-region" tabindex="-1">区域配置 Tab <a class="header-anchor" href="#tab-region" aria-label="Permalink to &quot;区域配置 Tab {#tab-region}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>区域模式</td><td>平台 / 多区域自选 / 固定区域</td></tr><tr><td><code>platform_distance_limit</code></td><td>多区域自选下进入「平台」的最大距离（<strong>米</strong>，默认 1000；0=不限制）</td></tr><tr><td><code>platform_latitude</code> / <code>platform_longitude</code></td><td>平台中心坐标（GCJ-02）</td></tr></tbody></table><p>各区域的距离限制在 <strong>区域管理 → 区域列表</strong> 的 <code>distance_limit</code> 字段单独配置。</p><p>与 <a href="/config/region">区域管理</a> 中各区域中心经纬度配合，用于距离门禁。</p><hr><h2 id="server-config" tabindex="-1">服务端 config.yaml <a class="header-anchor" href="#server-config" aria-label="Permalink to &quot;服务端 config.yaml {#server-config}&quot;">​</a></h2><h3 id="ip2region-离线库" tabindex="-1">ip2region 离线库 <a class="header-anchor" href="#ip2region-离线库" aria-label="Permalink to &quot;ip2region 离线库&quot;">​</a></h3><p>当 <code>ali_ip_location_provider = ip2region</code> 时使用。xdb 放在 <code>static/ip2region/</code>（与上传、日志同属运行期静态目录）。</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ip2region</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  v4_xdb_path</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">static/ip2region/base_full_v4.xdb</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  v6_xdb_path</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">static/ip2region/base_full_v6.xdb</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  searcher_pool_size</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">20</span></span></code></pre></div><p>从 ip2region 官方渠道下载商业包后，将 <code>base_full_v4.xdb</code>、<code>base_full_v6.xdb</code> 放入 <code>static/ip2region/</code>（详见该目录 README）。</p><ul><li><strong>v4 xdb 缺失</strong>：ip2region 整体不可用，系统仍可正常启动，IP 离线定位跳过（不影响发帖等主流程）。</li><li><strong>v6 xdb 缺失</strong>：仅 IPv6 客户端无法走 ip2region，IPv4 不受影响。</li></ul><h3 id="可信反向代理-cdn" tabindex="-1">可信反向代理（CDN） <a class="header-anchor" href="#可信反向代理-cdn" aria-label="Permalink to &quot;可信反向代理（CDN）&quot;">​</a></h3><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">deployment</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  trusted_proxy_cidrs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">127.0.0.1/32</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">10.0.0.0/8</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">172.16.0.0/12</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">192.168.0.0/16</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 接入 CDN 时追加回源网段，例如腾讯云 EdgeOne：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">223.109.0.0/16</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">111.4.0.0/16</span></span></code></pre></div><p>未正确配置时，Gin 可能把 CDN 出口 IP 当作客户端 IP，导致 IP 归属地偏差、区域距离误判。</p><hr><h2 id="api" tabindex="-1">API 一览 <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API 一览 {#api}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方法</th><th>路径</th><th>说明</th></tr></thead><tbody><tr><td>GET</td><td><code>/api/system/location</code></td><td>IP 定位；<code>ip</code> 留空则按提供方取客户端 IP</td></tr><tr><td>GET</td><td><code>/api/system/amap-config</code></td><td>C 端拉取前端高德 Key</td></tr><tr><td>GET</td><td><code>/api/system/amap/place/text</code></td><td>POI 关键字搜索</td></tr><tr><td>GET</td><td><code>/api/system/amap/weather</code></td><td>城市天气</td></tr><tr><td>POST</td><td><code>/api/admin/system/configs/amap-test</code></td><td>管理端高德连通性测试</td></tr></tbody></table><p><strong>开发环境</strong>：<code>local</code> / <code>dev</code> / <code>test</code> 下，内网 IP（127.0.0.1、局域网）会自动回退到测试公网 IP，便于联调 IP 属地。</p><hr><h2 id="业务行为说明" tabindex="-1">业务行为说明 <a class="header-anchor" href="#业务行为说明" aria-label="Permalink to &quot;业务行为说明&quot;">​</a></h2><ul><li><strong>发布笔记 / 评论</strong>：尽力写入 IP 属地快照；查询失败或凭证未配时不阻塞发布。</li><li><strong>已登录用户访问 <code>/api/system/location</code></strong>：成功后会更新 <code>users.register_location</code>。</li><li><strong>IP 定位不走熔断器</strong>：ip2region 离线查询与在线 API 分离；xdb 不可用时不影响系统其它模块。</li></ul><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/config/system-settings">系统配置总览</a> — 12 个 Tab 入口与建议配置顺序</li><li><a href="/config/region">区域管理</a> — 区域列表、中心点与业务模式</li><li><a href="/features/takeaway">外卖</a> · <a href="/features/errand">跑腿</a> — 依赖地图的业务配置</li></ul>`,34))])}const m=i(r,[["render",l]]);export{y as __pageData,m as default};
